#!/usr/bin/env python3
"""Writes app_prompts.py from the Dart export, so training prompts cannot drift.

Usage:
  flutter test training/export_prompts_test.dart --dart-define=EXPORT_PATH=/abs/prompt_export.json
  python3 -I training/make_app_prompts.py /abs/prompt_export.json training/app_prompts.py
"""
import json
import sys

d = json.load(open(sys.argv[1], encoding='utf-8'))
parts = [
    '"""The app\'s fixed prompt strings. Generated by make_app_prompts.py; do not edit."""\n\n',
    f'PLAN_SYSTEM = {d["planSystem"]!r}\n\n',
    f'REPLY_SYSTEM = {d["replySystem"]!r}\n\n',
    f'TONE_STYLES = {d["toneStyles"]!r}\n\n',
    f'PERSONALITIES = {d["personalities"]!r}\n',
]
open(sys.argv[2], 'w', encoding='utf-8').write(''.join(parts))
print('wrote', sys.argv[2])
